  "footer.listVenue": "உங்கள் மையத்தைப் பதிவு செய்யுங்கள்",
  "footer.staff": "பணியாளர் உள்நுழைவு",
  "pricing.title": "மையங்களுக்கான கட்டணங்கள்",
  "pricing.intro": "உங்களிடம் உள்ள கோர்ட்டுகள், அறைகளின் எண்ணிக்கையைப் பொறுத்து ஒரே ஒரு மாதக் கட்டணம். ஒவ்வொரு திட்டத்திலும் எல்லா அம்சங்களும் உண்டு. முன்பதிவுகளுக்குக் கமிஷன் இல்லை, அமைப்புக் கட்டணம் இல்லை, ஒப்பந்தம் இல்லை.",
  "pricing.introFlat": "எல்லா மையங்களுக்கும் ஒரே மாதக் கட்டணம், எல்லா அம்சங்களுடன். முன்பதிவுகளுக்குக் கமிஷன் இல்லை, அமைப்புக் கட்டணம் இல்லை, ஒப்பந்தம் இல்லை.",
  "pricing.introFree": "நாங்கள் தொடங்கும் வரை உங்கள் மையத்தைப் பட்டியலிடுவது இலவசம். மையங்களுக்கான விலைகள் இன்னும் நிர்ணயிக்கப்படவில்லை: அவை எதுவாக இருந்தாலும் இந்தப் பக்கத்தில் வெளியிடப்படும்.",
  "pricing.flat": "எல்லா மையங்களுக்கும் ஒரே கட்டணம்: மாதம் {cur}{fee}.",
  "pricing.free": "அறிமுகக் காலத்தில் பதிவு செய்வது இலவசம்.",
  "pricing.month": "மாதத்திற்கு",
  "pricing.range": "{from}–{to} கோர்ட்டுகள் அல்லது அறைகள்",
  "pricing.one": "1 கோர்ட் அல்லது அறை",
  "pricing.upward": "{from} அல்லது அதற்கு மேற்பட்ட கோர்ட்டுகள் அல்லது அறைகள்",
  "pricing.extra": "பின்னர் கூடுதலான ஒவ்வொன்றுக்கும் {cur}{fee}",
  "pricing.included": "எல்லாத் திட்டங்களிலும்",
  "pricing.inc1": "ஆன்லைன் முன்பதிவு, தொடர் முன்பதிவுகள், வகுப்புகள், உறுப்பினர் சந்தாக்கள், பாஸ்கள், சேமிப்புக் கிரெடிட்",
  "pricing.inc2": "நாள்காட்டி அழைப்புடன் மின்னஞ்சல் உறுதிப்படுத்தல்கள், முந்தைய நாள் நினைவூட்டல்கள்",
  "pricing.inc3": "அவசரச் செய்திகளுக்கு WhatsApp — நீங்கள் ரத்து செய்யும் அல்லது மாற்றும் முன்பதிவு, காத்திருப்புப் பட்டியலில் இடம் — கட்டணமின்றி",
  "pricing.inc4": "அறிக்கைகள், பணியாளர் கணக்குகள், கிளைகள்",
  "pricing.money": "உங்கள் வாடிக்கையாளர்களின் பணம்",
  "pricing.money1": "வாடிக்கையாளர்கள் உங்கள் கவுண்டரில் அல்லது ஆன்லைனில் ({payMethods}) உங்கள் சொந்த {gateway} கணக்கிற்கு நேரடியாக உங்களுக்குச் செலுத்துவார்கள். நாங்கள் உங்கள் பணத்தை வைத்திருப்பதில்லை, எந்தப் பங்கும் எடுப்பதில்லை. {gateway} ஒவ்வொரு கட்டணத்திற்கும் தனது சொந்தக் கட்டணத்தை வசூலிக்கும்; அது உங்களுக்கும் {gateway} க்கும் இடையிலான ஒப்பந்தம்.",
  "pricing.extras": "விருப்பத்தேர்வு",
  "pricing.whatsapp": "அவசரச் செய்திகள் மட்டுமல்லாமல் எல்லாச் செய்திகளுக்கும் WhatsApp: {n} செய்திகளுக்கு {cur}{price}, முன்கூட்டியே செலுத்த வேண்டும். பின்னர் எதற்கும் கட்டணம் விதிக்கப்படாது.",
  "pricing.terms": "உங்களுக்குக் கட்டணம் விதிக்கப்படும் முறை",
  "pricing.terms1": "அமைக்கும்போது எதுவும் இல்லை. நேரலைக்கு வந்ததும் {months} இலவசம், பின்னர் மாதம் ஒரு விலைப்பட்டியல், 14 நாட்களுக்குள் செலுத்த வேண்டும்.",
  "pricing.terms2": "ஒவ்வொரு மாதமும் விலைப்பட்டியல் தயாரிக்கும்போது கோர்ட்டுகளும் அறைகளும் கணக்கிடப்படும்; மாதம் முழுவதும் பயன்பாட்டில் இல்லாதவை கணக்கிடப்படாது.",
  "pricing.monthsOne": "அந்த மாதத்தின் மீதமும் மேலும் 1 மாதமும்",
  "pricing.monthsMany": "அந்த மாதத்தின் மீதமும் மேலும் {n} மாதங்களும்",
  "pricing.monthsNone": "அந்த மாதத்தின் மீதம்",
  "pricing.cta": "உங்கள் மையத்தைப் பதிவு செய்யுங்கள்",
  "pricing.see": "கட்டணங்களைப் பாருங்கள்",
  "apply.title": "உங்கள் மையத்தை {site} இல் பதிவு செய்யுங்கள்",
  "apply.intro": "கோர்ட்டுகள், ஜிம்கள், நீச்சல் குளங்கள், வகுப்புகள்: ஆன்லைனில் முன்பதிவுகளை ஏற்று, உங்கள் சொந்தக் கணக்கிற்கு நேரடியாக ஆன்லைனில் பணம் பெற்று, அமைதியான நேரங்களையும் நிரப்புங்கள். இன்றே இலவசமாகப் பதிவு செய்து உங்கள் மையத்தை அமையுங்கள். அது உண்மையானது என்று நாங்கள் சரிபார்த்த பின் வாடிக்கையாளர்கள் அதைப் பார்ப்பார்கள்.",
  "apply.business": "மையத்தின் பெயர்",
  "apply.area": "பகுதி",
  "apply.address": "முகவரி",
  "apply.venuePhone": "மையத்தின் தொலைபேசி",
