  "apply.passwordHint": "குறைந்தது 10 எழுத்துகள். இதைக் கொண்டு நீங்கள் உள்நுழைவீர்கள்.",
  "apply.message": "நாங்கள் தெரிந்துகொள்ள வேண்டியது ஏதேனும் உண்டா? கோர்ட்டுகள், விளையாட்டுகள், திறந்திருக்கும் நேரம்.",
