  "apply.doneTitle": "உங்கள் கணக்கு தயார்",
  "apply.doneBody": "{email} மற்றும் நீங்கள் தேர்ந்தெடுத்த கடவுச்சொல்லுடன் உள்நுழைந்து, உங்கள் மையத்தை அமையுங்கள்.",
  "apply.checkTitle": "உங்கள் மின்னஞ்சலைப் பாருங்கள்",
  "apply.checkBody": "{email} க்கு ஒரு இணைப்பை அனுப்பியுள்ளோம். உங்கள் மின்னஞ்சலை உறுதிப்படுத்த அதைப் பின்பற்றுங்கள், உங்கள் கணக்கு உடனே திறக்கும். இணைப்பு 7 நாட்களுக்குச் செல்லுபடியாகும்.",
  "apply.mapLabel": "வரைபடத்தில் அது எங்கே உள்ளது?",
  "apply.mapHint": "வரைபடத்தில் உங்கள் மையத்தின் நுழைவாயிலைத் தட்டுங்கள். குறியை நகர்த்த இழுங்கள்.",
  "apply.findAddress": "முகவரியைத் தேடு",
  "apply.useLocation": "நான் மையத்தில் இருக்கிறேன்: என் இருப்பிடத்தைப் பயன்படுத்து",
  "apply.looking": "தேடுகிறது…",
  "apply.found": "சாம்பல் வளையம் உங்கள் முகவரி காட்டும் இடம். இப்போது உங்கள் மையத்தின் நுழைவாயிலைத் தட்டுங்கள்.",
  "apply.notFound": "அந்த முகவரியை வரைபடத்தில் கண்டறிய முடியவில்லை. வரைபடத்தை உங்கள் மையத்திற்கு நகர்த்தி அதைத் தட்டுங்கள்.",
  "apply.pinned": "குறிக்கப்பட்டது. சரியாக இல்லையென்றால் குறியை இழுத்து நகர்த்துங்கள்.",
  "apply.locationFailed": "உங்கள் இருப்பிடத்தைப் பெற முடியவில்லை. அதற்குப் பதிலாக வரைபடத்தைத் தட்டுங்கள்.",
  "apply.needPin": "மையம் இருக்கும் இடத்தை வரைபடத்தில் குறியிடுங்கள்.",
  "confirm.title": "உங்கள் மின்னஞ்சல் உறுதிப்படுத்தப்பட்டது",
  "confirm.body": "உங்கள் கணக்கு திறக்கப்பட்டது. உங்கள் மின்னஞ்சலுடனும் நீங்கள் தேர்ந்தெடுத்த கடவுச்சொல்லுடனும் உள்நுழைந்து உங்கள் மையத்தை அமையுங்கள்: அது நேரலைக்கு வந்ததும் வாடிக்கையாளர்கள் அதைப் பார்ப்பார்கள்.",
  "confirm.unknownTitle": "அந்த இணைப்பு காலாவதியாகிவிட்டது அல்லது ஏற்கெனவே பயன்படுத்தப்பட்டது",
  "confirm.unknownBody": "நீங்கள் ஏற்கெனவே உறுதிப்படுத்தியிருந்தால், உங்கள் கணக்கு திறந்துள்ளது: உள்நுழையுங்கள். 7 நாட்களுக்கு முன்பு பதிவு செய்திருந்தால், தயவுசெய்து மீண்டும் பதிவு செய்யுங்கள்.",
  "confirm.again": "மீண்டும் பதிவு செய்",
