  "lang.label": "மொழி",
  "home.heroTitle": "சில நொடிகளில் கோர்ட்டை முன்பதிவு செய்யுங்கள்.",
  "home.heroBody": "பூப்பந்து, டென்னிஸ், பிக்கல்பால், ஃபுட்சல் — நேரடி இருப்பைப் பாருங்கள், உங்கள் நேரங்களைத் தேர்ந்தெடுங்கள், உடனே முன்பதிவுக் குறியீட்டைப் பெறுங்கள். அழைக்கத் தேவையில்லை, காத்திருக்கத் தேவையில்லை. ரொம்ப சுலபம்!",
