  "rules.who": "ஒவ்வொரு நபருக்கும் அல்லது குடும்பத்திற்கும்",
  "access.membersBadge": "உறுப்பினர்களுக்கு மட்டும்",
  "access.membersBody": "உறுப்பினர்கள் மட்டுமே இங்கே முன்பதிவு செய்ய முடியும். ஏற்கெனவே உறுப்பினரா? உள்நுழைந்து, உங்கள் கணக்கை உங்கள் உறுப்பினர் தகுதியுடன் இணைக்க மையத்திடம் கேளுங்கள்.",
  "access.youAreMember": "உறுப்பினர்களுக்கு மட்டும் — நீங்கள் இங்கே முன்பதிவு செய்யலாம்.",
  "member.joinTitle": "உறுப்பினராகுங்கள்",
  "member.joinBody": "ஆன்லைனில் சேர்ந்து மையத்திற்கு நேரடியாகச் செலுத்துங்கள். பணம் செலுத்தியவுடன், இன்றே உங்கள் உறுப்பினர் சந்தா தொடங்கும்.",
  "member.renewTitle": "உங்கள் உறுப்பினர் சந்தா",
