  "done.court": "கோர்ட்",
  "done.date": "தேதி",
  "done.time": "நேரம்",
  "done.promoDiscount": "ப்ரோமோ தள்ளுபடி",
  "done.total": "மொத்தம்",
  "done.totalValue": "{cur}{amount} (கவுண்டரில் செலுத்துங்கள்)",
  "done.deposit": "முன்பணம்",
  "done.depositValue": "{cur}{amount}, உபகரணங்களுடன் திருப்பித் தரப்படும்",
  "done.promoRejected": "உங்கள் ப்ரோமோ குறியீடு பயன்படுத்தப்படவில்லை: {reason}",
  "done.sessions": "அமர்வுகள்",
  "done.skipped": "தவிர்க்கப்பட்டது — {reason}",
  "done.icsFile": ".ics கோப்பு",
  "done.close": "முடிந்தது",
  "queue.onTitle": "நீங்கள் காத்திருப்புப் பட்டியலில் உள்ளீர்கள்",
  "queue.onBody": "{time} இல் {court} க்கு எண் {position}.",
  "queue.onNote": "அது காலியானால், அதிக நேரம் காத்திருந்தவருக்கு அந்த நேரம் வழங்கப்படும். உள்நுழைந்த வாடிக்கையாளர்கள் தங்கள் கணக்குப் பக்கத்தில் அந்த வாய்ப்பைப் பார்ப்பார்கள்.",
  "queue.taken": "இந்த நேரம் முன்பதிவாகிவிட்டது. காத்திருப்புப் பட்டியலில் சேருங்கள், அது காலியானால் உங்களுக்கு வழங்குவோம்.",
  "queue.cancel": "ரத்து செய்",
  "queue.join": "காத்திருப்புப் பட்டியலில் சேர்",
  "queue.joining": "சேர்கிறது…",
  "queue.failed": "காத்திருப்புப் பட்டியலில் சேர முடியவில்லை",
  "search.title": "கோர்ட் தேடுங்கள்",
  "search.intro": "எல்லா மையங்களிலும் ஒரே நேரத்தில் தேடுங்கள் — ஒரு விளையாட்டையும் நேரத்தையும் தேர்ந்தெடுத்து, எது காலியாக உள்ளது என்று பாருங்கள்.",
  "search.find": "நீங்கள் என்ன செய்ய விரும்புகிறீர்கள்?",
  "search.findHint": "ஒரு விளையாட்டு அல்லது செயல்பாட்டைத் தட்டச்சு செய்யுங்கள்: ஃபுட்சால், யோகா, கயாக்…",
  "search.findNone": "இங்கே இதை இன்னும் யாரும் வழங்கவில்லை.",
