  "err.PLAYERS_RANGE": "எத்தனை பேர் விளையாடுவார்கள் என்று சொல்லுங்கள்: 1 முதல் {max} வரை.",
  "err.MIN_HOURS": "இங்கே ஒரு முன்பதிவு குறைந்தது {min} மணிநேரம்.",
  "err.POLICY_START": "இங்கே அந்த நேரத்தில் முன்பதிவுகள் தொடங்குவதில்லை. {rule}",
