  "phone.smsText": "{site}: உங்கள் குறியீடு {code}. இது 10 நிமிடங்களுக்குச் செல்லுபடியாகும். இதை யாருடனும் பகிராதீர்கள்.",
  "phone.chooseTitle": "உங்கள் தொலைபேசி எண்ணைச் சரிபாருங்கள்",
  "phone.viaWhatsapp": "WhatsApp மூலம் சரிபார்",
  "phone.viaWhatsappNote": "உங்கள் சொந்த WhatsApp கணக்கிலிருந்து சரிபார்ப்புச் செய்தியை அனுப்புங்கள். குறியீடு எதுவும் பெறத் தேவையில்லை.",
  "phone.recommended": "பரிந்துரைக்கப்படுகிறது",
  "phone.viaSms": "SMS மூலம் சரிபார்",
  "phone.viaSmsNote": "குறுஞ்செய்தி மூலம் ஒருமுறைக் குறியீட்டைப் பெறுங்கள்.",
  "phone.viaCodeWhatsapp": "WhatsApp இல் குறியீட்டைப் பெறு",
  "phone.viaCodeWhatsappNote": "WhatsApp செய்தியில் ஒருமுறைக் குறியீட்டைப் பெறுங்கள்.",
  "phone.waStep": "செய்தி தயாராக உள்ள WhatsApp ஐத் திறக்கப் பொத்தானைத் தட்டி, பின்னர் அனுப்பு என்பதை அழுத்துங்கள். {phone} இலிருந்து அனுப்புங்கள்.",
  "phone.waOpen": "WhatsApp ஐத் திறந்து அனுப்பு",
  "phone.waWaiting": "உங்கள் செய்திக்காகக் காத்திருக்கிறது… அது வந்ததும் இந்தப் பக்கம் தானாகவே தொடரும்.",
  "phone.smsSent": "{phone} க்கு SMS மூலம் 6 இலக்கக் குறியீட்டை அனுப்பியுள்ளோம். அது 10 நிமிடங்களுக்குச் செல்லுபடியாகும்.",
