  "err.PHONE_CODE_LIMIT": "இப்போதைக்கு போதுமான குறியீடுகள் அனுப்பப்பட்டுவிட்டன. பின்னர் மீண்டும் முயலுங்கள்.",
  "err.PHONE_CODE_EXPIRED": "அந்தக் குறியீடு காலாவதியாகிவிட்டது. புதிய ஒன்றைக் கேளுங்கள்.",
  "err.PHONE_CODE_WRONG": "அது சரியான குறியீடு அல்ல. சரிபார்த்து மீண்டும் முயலுங்கள்.",
  "err.PHONE_NEEDED": "மையம் உங்களைத் தொடர்புகொள்ள, முதலில் உங்கள் கணக்கில் தொலைபேசி எண்ணைச் சேருங்கள்.",
  "err.PHONE_UNVERIFIED": "முதலில் உங்கள் தொலைபேசி எண்ணைச் சரிபாருங்கள்: அதற்கு WhatsApp இல் ஒரு குறியீட்டை அனுப்புவோம்.",
  "err.STRIKES_COUNTER": "{n} முன்பதிவுகளுக்கு வராமல் இருந்ததால் அல்லது தாமதமாக ரத்து செய்ததால், இந்த மையம் உங்கள் எண்ணிலிருந்து கவுண்டரில் மட்டுமே முன்பதிவுகளை ஏற்கும்.",
  "receipt.why.lateCancelled": "இலவச ரத்து நேரத்திற்குப் பிறகு ரத்து செய்யப்பட்டது: மையம் தனது கட்டணத்தை வைத்துக்கொண்டது, திருப்பித் தரப்பட்டது இதுதான்.",
  "receipt.why.disputed": "வாடிக்கையாளர் தனது வங்கியிடம் இந்தக் கட்டணத்தை மறுத்தார், வங்கி அதை அவருக்குத் திருப்பித் தந்தது.",
  "einv.title": "மின்-விலைப்பட்டியல் தேவையா?",
  "einv.intro": "உங்கள் பெயரிலோ உங்கள் நிறுவனத்தின் பெயரிலோ LHDN மின்-விலைப்பட்டியல் தேவைப்பட்டால், நீங்கள் செலுத்திய மாதத்தின் இறுதிக்குள் இங்கே கேளுங்கள். இல்லையெனில், இந்த விற்பனை மையத்தின் மாதாந்திர ஒருங்கிணைந்த மின்-விலைப்பட்டியலில் சேர்க்கப்படும்.",
