  "split.progress": "நண்பர்களின் {of} பங்குகளில் {paid} செலுத்தப்பட்டன.",
  "split.message": "{venue} இல் என் முன்பதிவு, {date}: உங்கள் பங்கான {share} ஐ இங்கே செலுத்துங்கள்: {link}",
  "split.payTitle": "{venue} இல் {host} இன் முன்பதிவு",
  "split.payWhat": "{court}, {date}, {time}",
  "split.payShare": "உங்கள் பங்கு: {share}",
  "split.payTerms": "நீங்கள் {venue} க்கு அதன் சொந்தக் கட்டணப் பக்கம் வழியாக நேரடியாகச் செலுத்தி ரசீது பெறுவீர்கள். முன்பதிவு ரத்து செய்யப்பட்டால், அல்லது உங்களுடையது வருவதற்கு முன்பே எல்லாப் பங்குகளும் செலுத்தப்பட்டுவிட்டால், மையம் அதை உங்களுக்குத் திருப்பித் தர வேண்டும்.",
  "split.pay": "என் பங்கைச் செலுத்து",
  "split.paying": "கட்டணப் பக்கத்தைத் திறக்கிறது…",
  "split.closed.paid": "இந்த முன்பதிவு முழுமையாகச் செலுத்தப்பட்டது. {host} உடன் கணக்கைத் தீர்த்துக்கொள்ளுங்கள்.",
  "split.closed.cancelled": "இந்த முன்பதிவு ரத்து செய்யப்பட்டது.",
  "split.closed.started": "இந்த முன்பதிவு தொடங்கிவிட்டது. {host} உடன் கணக்கைத் தீர்த்துக்கொள்ளுங்கள்.",
  "split.closed.full": "எல்லாப் பங்குகளும் செலுத்தப்பட்டுவிட்டன.",
  "mine.lateCancelNote": "அதன் பிறகும் இங்கே ரத்து செய்யலாம், ஆனால் நீங்கள் செலுத்தியதில் {pct}% ஐ மையம் வைத்துக்கொள்ளும்.",
  "mine.lateCancelConfirm": "இலவச ரத்து நேரம் கடந்துவிட்டது. நீங்கள் செலுத்தியதில் {pct}% ஐ மையம் வைத்துக்கொள்ளும். இருந்தாலும் ரத்து செய்யவா?",
  "mine.lateStrikeConfirm": "இலவச ரத்து நேரம் கடந்துவிட்டது, எனவே இது இந்த மையத்தில் உங்கள் எண்ணுக்கு எதிராகத் தாமதமான ரத்தாகக் கணக்கிடப்படும். இருந்தாலும் ரத்து செய்யவா?",
  "mine.lateCancelDone": "ரத்து செய்யப்பட்டது. மையம் {kept} ஐ வைத்துக்கொண்டது; மீதி நீங்கள் செலுத்திய வழியிலேயே திரும்பும்.",
  "mine.refundGateway": "{amount} நீங்கள் ஆன்லைனில் செலுத்திய வழிக்குத் திரும்பி வருகிறது. அது தெரிய சில நாட்கள் ஆகலாம்.",
  "mine.refundCredit": "{amount} இந்த மையத்தில் உங்கள் கிரெடிட்டில் சேர்க்கப்பட்டது.",
  "mine.refundStaff": "நீங்கள் ஆன்லைனில் செலுத்திய {amount} ஐ மையம் திருப்பித் தரும்.",
