  "hire.title": "தனியார் வாடகை மற்றும் நிகழ்வுகள்",
  "hire.intro": "போட்டி, நிறுவன விளையாட்டு நாள், விருந்து அல்லது பள்ளி நிகழ்வைத் திட்டமிடுகிறீர்களா? உங்கள் எண்ணத்தை {venue} இடம் சொல்லுங்கள், அவர்கள் விலையுடன் உங்களைத் தொடர்புகொள்வார்கள்.",
