  "waiver.intro": "முன்பதிவு செய்யும் அனைவரும் இதை ஒப்புக்கொள்ள வேண்டும் என {venue} கேட்கிறது. முன்பதிவின்போது பெட்டியைத் தேர்வு செய்வதன் மூலம் ஒப்புக்கொள்கிறீர்கள்; இடம் வார்த்தைகளை மாற்றும் வரை ஒருமுறை மட்டுமே கேட்கப்படும்.",
