  "gift.paidBody": "அதை உங்களுக்கு மின்னஞ்சலிலும் அனுப்பியுள்ளோம். குறியீடு: {code}",
  "gift.notPaid": "எந்தக் கட்டணமும் வசூலிக்கப்படவில்லை. மையத்தின் பக்கத்திலிருந்து மீண்டும் முயலலாம்.",
