  // Online applications to be approved for an activity (lib/approvals.ts); apr.r/status/slot/ev also in the staff dictionary.
  "apr.accountLink": "செயல்பாடுகளுக்கான ஒப்புதல்கள்: உங்கள் விண்ணப்பங்களும் அவற்றின் நிலையும்",
  "apr.title": "செயல்பாடுகளுக்கான ஒப்புதல்கள்",
  "apr.intro": "சில செயல்பாடுகளை முன்பதிவு செய்வதற்கு முன் மையத்தின் ஒப்புதல் தேவை: பாதுகாப்புச் சோதனை, அறிமுகப் பயிற்சி அல்லது சான்றிதழ். இங்கே விண்ணப்பியுங்கள், ஒவ்வொரு விண்ணப்பத்தின் நிலையையும் பாருங்கள், மையம் மேலும் கேட்டால் பதிலளியுங்கள்.",
  "apr.signInFirst": "விண்ணப்பிக்க உள்நுழையுங்கள்: ஒப்புதல் தனிப்பட்டது, எனவே அது உங்கள் கணக்கைச் சேர்ந்தது.",
  "apr.notOffered": "இந்த மையம் அந்தச் செயல்பாட்டுக்கு இணையத்தில் விண்ணப்பங்களை ஏற்பதில்லை. கவுண்டரில் கேளுங்கள்.",
  "apr.sent": "அனுப்பப்பட்டது. மையம் அதைப் பரிசீலிக்கும்; முடிவு மின்னஞ்சலில் தெரிவிக்கப்படும்.",
  "apr.none": "இன்னும் விண்ணப்பங்கள் இல்லை. இணையத்தில் விண்ணப்பிக்கக்கூடிய செயல்பாடுகளை மையத்தின் பக்கம் காட்டுகிறது.",
  "apr.backToAccount": "என் கணக்குக்குத் திரும்பு",
  "apr.cardTitle": "{venue} இல் {activity}",
  "apr.theyAsked": "{name} கேட்கிறார்:",
  "apr.answerSent": "பதில் அனுப்பப்பட்டது. அது மீண்டும் பரிசீலனைக்குச் செல்கிறது.",
  "apr.sendAnswer": "பதிலை அனுப்பு",
  "apr.why": "காரணம்: {reason}",
  "apr.slotLine": "கேட்ட நேரம்: {slot}",
  "apr.slotGoneHelp": "அந்த நேரம் இனி உங்களுக்காக ஒதுக்கப்படவில்லை. ஒப்புதல் கிடைத்ததும் வேறு நேரத்தை முன்பதிவு செய்யலாம், அல்லது இதன் காத்திருப்புப் பட்டியலில் சேரலாம்.",
  "apr.slotGoneLink": "மையத்தின் நேரங்களைப் பாருங்கள்",
  "apr.bookSession": "நேரில் செய்ய வேண்டிய படிக்கான அமர்வை முன்பதிவு செய்",
  "apr.askSlot": "ஒரு நேரத்தைக் கேள்",
  "apr.sessionBooked": "அமர்வு முன்பதிவு செய்யப்பட்டது. அதன் உறுதிப்படுத்தல் வருகிறது.",
  "apr.slotHeld": "உங்கள் விண்ணப்பம் பரிசீலிக்கப்படும்போது நேரம் ஒதுக்கப்பட்டுள்ளது.",
