  "apr.yourDocuments": "உங்கள் ஆவணங்கள்:",
  "apr.withdrawConfirm": "இந்த விண்ணப்பத்தைத் திரும்பப் பெறவா? அதற்காக ஒதுக்கப்பட்ட நேரம் விடுவிக்கப்படும்.",
  "apr.withdrawn": "திரும்பப் பெறப்பட்டது.",
  "apr.withdraw": "திரும்பப் பெறு",
  "apr.renew": "புதுப்பி",
  "apr.applyAgain": "மீண்டும் விண்ணப்பி",
  "apr.explain.revoked": "மையம் இந்த ஒப்புதலைத் திரும்பப் பெற்றுள்ளது. மீண்டும் விண்ணப்பியுங்கள், அல்லது கவுண்டரில் கேளுங்கள்.",
  "apr.explain.lapsed": "இந்த ஒப்புதல் {date} அன்று காலாவதியானது. மீண்டும் முன்பதிவு செய்ய அதைப் புதுப்பியுங்கள்.",
  "apr.explain.approvedUntil": "{date} வரை ஒப்புதல்: இந்தச் செயல்பாட்டை இங்கே இணையத்தில் முன்பதிவு செய்யலாம்.",
  "apr.explain.approved": "ஒப்புதல் கிடைத்தது: இந்தச் செயல்பாட்டை இங்கே இணையத்தில் முன்பதிவு செய்யலாம்.",
  "apr.explain.in_person_due": "இணையப் பகுதி ஏற்கப்பட்டது. நேரில் இன்னும் செய்ய வேண்டியது: {step}. ஊழியர்கள் அதைப் பதிவு செய்யும் வரை இந்தச் செயல்பாட்டை முன்பதிவு செய்ய முடியாது, அதற்குக் கதவுக் குறியீடும் வழங்கப்படாது.",
  "apr.explain.pending": "மையம் பரிசீலிக்கக் காத்திருக்கிறது. யாரும் நடவடிக்கை எடுக்காவிட்டால் {date} அன்று காலாவதியாகும். ஒப்புதல் கிடைக்கும் வரை கட்டணம் இல்லை, முன்பதிவும் இல்லை.",
  "apr.explain.info_requested": "மையம் மேலும் தகவல் கேட்கிறது. {date} க்குள் பதிலளியுங்கள், இல்லையெனில் காலாவதியாகும்.",
  "apr.explain.rejected": "மையம் இந்த விண்ணப்பத்தை நிராகரித்தது.",
  "apr.explain.withdrawn": "இந்த விண்ணப்பத்தை நீங்கள் திரும்பப் பெற்றீர்கள்.",
  "apr.explain.expired": "இந்த விண்ணப்பம் காலாவதியானது: நேரத்தில் பதிலளிக்கப்படவில்லை. நீங்கள் மீண்டும் விண்ணப்பிக்கலாம்.",
  "apr.slotHeldUntil": "{date} வரை உங்களுக்காக ஒதுக்கப்பட்டுள்ளது",
  "apr.failed": "அது வேலை செய்யவில்லை. மீண்டும் முயலுங்கள்.",
