  "apr.applyTitle": "{venue} இல் {activity} க்கு விண்ணப்பியுங்கள்",
  "apr.applyIntro": "மையம் இதை இணையத்தில் பரிசீலிக்கிறது: பதிவு செய்வதற்காக மட்டும் கவுண்டருக்கு வர வேண்டியதில்லை. முடிவு மின்னஞ்சலில் தெரிவிக்கப்படும்.",
