  "apr.r.declared": "உறுதிமொழி {date} அன்று தேர்வு செய்யப்பட்டது",
  "apr.r.watched": "விளக்க வீடியோ பார்த்ததாக {date} அன்று உறுதிப்படுத்தப்பட்டது",
  "apr.r.waiverAgreed": "பொறுப்புத் துறப்பு ஒப்புக்கொள்ளப்பட்டது",
