  "apr.r.askPrompt": "{name} உங்களுக்கு என்ன சொல்ல அல்லது அனுப்ப வேண்டும்?",
  "apr.r.rejectPrompt": "{name} இன் விண்ணப்பம் ஏன் நிராகரிக்கப்படுகிறது? அவருக்குத் தெரிவிக்கப்படும்.",
